def slug(value: str) -> str:
    value = value.casefold().replace("3d", "three-d")
    value = re.sub(r"[^a-z0-9]+", "-", value).strip("-")
    return value or "root"


def rust_slug(value: str) -> str:
    return slug(value).replace("-", "_")


