def task(
    identifier: str,
    title: str,
    requirements: list[int],
    designs: list[int],
    validations: list[str],
    outcome: str,
    reads: list[str],
    writes: list[str],
    done: str,
    dependency: str | list[str] | None = None,
    cargo_features: dict[str, str] | None = None,
    validation_packages: list[str] | None = None,
    locked: bool = False,
    criterion_ids: list[str] | None = None,
    feature_scoped: bool = False,
    registered_source_edits: list[str] | None = None,
) -> dict[str, object]:
    dependencies = [] if dependency is None else ([dependency] if isinstance(dependency, str) else list(dependency))
    normalized_writes = list(dict.fromkeys(writes))
    registered_source_edit_crates = set(registered_source_edits or [])
    for crate, root in CRATE_ROOTS.items():
        source_prefix = f"crates/{crate}/src/"
        binary_prefix = f"crates/{crate}/src/bin/"
        source_writes = [
            path
            for path in normalized_writes
            if path.startswith(source_prefix) and not path.startswith(binary_prefix)
        ]
        if (
            not source_writes
            or root in normalized_writes
            or crate in registered_source_edit_crates
        ):
            continue
        automatic_prefixes = AUTO_MODULE_PREFIXES.get(crate, ())
        if automatic_prefixes and all(path.startswith(automatic_prefixes) for path in source_writes):
            continue
        normalized_writes.append(root)
    return {
        "id": identifier,
        "title": title,
        "requirements": requirements,
        "criterion_ids": criterion_ids or [],
        "feature_scoped": feature_scoped,
        "designs": designs,
        "validations": validations,
        "outcome": outcome,
        "reads": reads,
        "writes": normalized_writes,
        "done": done,
        "dependencies": dependencies,
        "cargo_features": cargo_features or {},
        "validation_packages": validation_packages or [],
        "locked": locked,
    }


