def requirement_criteria() -> dict[int, list[str]]:
    text = (ROOT / "requirements.md").read_text(encoding="utf-8")
    criteria: dict[int, list[str]] = defaultdict(list)
    current: int | None = None
    in_acceptance = False
    for line in text.splitlines():
        heading = re.match(r"^### Requirement (\d+)\b", line)
        if heading:
            current = int(heading.group(1))
            in_acceptance = False
            continue
        if line.casefold() == "#### acceptance criteria":
            in_acceptance = True
            continue
        if line.startswith("#"):
            in_acceptance = False
        if current is not None and in_acceptance:
            criterion = re.match(r"^(\d+)\.\s+\S", line)
            if criterion:
                criteria[current].append(f"{current}.{criterion.group(1)}")
    expected = set(range(1, 46))
    if set(criteria) != expected:
        raise RuntimeError(f"requirements mismatch: expected {expected}, found {set(criteria)}")
    return dict(criteria)


