def write_tasks(tasks: list[dict[str, object]], criteria: dict[int, list[str]]) -> None:
    annotations = existing_task_annotations()
    waves = task_waves(tasks)
    lines = [
        "# Tasks: Native Rust/GPUI Comfy parity",
        "",
        "Every checkbox is an independently executable implementation leaf. Wave numbers are computed from explicit dependencies. Tensor/operator, device, model, sampler, scheduler, latent, and node breadth leaves in the same wave use disjoint Rust modules, fixtures, and lab records; generated module manifests let each leaf compile without editing a shared root, and serialized integration leaves own central closure output. No task launches or connects to ComfyUI in production code.",
        "",
        "Repository validation uses `./script/clippy`, never `cargo clippy`. Task-specific tests supplement, not replace, the strict spec and closure gates.",
        "",
        "CPU and Apple Metal are the certified baseline backends. Signed CPU attestation creation/refresh and live observations for optional accelerators are external release-certification gates, not executable task checkboxes. CoreX implementation beyond the compiled fail-closed typed-Unbound structural adapter is owned by `.agents/specs/comfy-corex-enablement/`.",
        "",
        "Evidence retained beneath an unchecked task is historical pre-reopen evidence only. It does not satisfy completion after a normative design, ownership, implementation, or validation change; the task must receive fresh post-change evidence before its checkbox may be restored.",
        "",
    ]
    for number, item in enumerate(tasks, 1):
        outcome = normalize_generated_spec_text(item["outcome"])
        done = normalize_generated_spec_text(item["done"])
        if item["id"] == "comfy-parity-native-device-amd-rocm-comfy-model-0014":
            outcome += (
                " Extend the private worker wire through protocol 6 and operation-support schema 2; "
                "preserve the exact legacy v5/schema-1 decoder and append the linear-algebra variant "
                "without changing any prior postcard discriminant."
            )
            done += (
                " Mixed-version tests reject legacy framing before decoding a changed payload, schema-1 "
                "support remains independently decodable, and protocol-6/schema-2 capability rows round-trip "
                "without same-version ambiguity."
            )
        annotation = annotations.get(str(item["id"]), {})
        checkbox = "x" if annotation.get("complete") is True else " "
        requirements = sorted(set(int(value) for value in item["requirements"]))
        explicit_criterion_ids = [str(value) for value in item["criterion_ids"]]
        criterion_ids = explicit_criterion_ids or [
            criterion for requirement in requirements for criterion in criteria[requirement]
        ]
        designs = ", ".join(f"D{value}" for value in item["designs"])
        validations = ", ".join(str(value) for value in item["validations"])
        reads = ", ".join(str(value) for value in item["reads"])
        writes = ", ".join(str(value) for value in item["writes"]) or "none"
        dependencies = [str(value) for value in item["dependencies"]]
        dependency = ", ".join(dependencies) if dependencies else "none"
        validation_command = f"{validations}; commands: {task_validation_commands(item)}"
        wave = waves[str(item["id"])]
        lines.extend([
            f"- [{checkbox}] {number}. {item['title']}",
            f"  - _id: {item['id']}",
            f"  - Outcome: {outcome}",
            f"  - Wave: {wave}",
            f"  - _Wave: {wave}",
            f"  - Dependencies: {dependency}",
        ])
        if dependencies:
            lines.append(f"  - _Blocked_by: {', '.join(dependencies)}")
        lines.extend([
            f"  - Reads: {reads}",
            f"  - _Reads: {reads}",
            f"  - Writes: {writes}",
            f"  - _Writes: {writes}",
            f"  - Requirements: {', '.join(criterion_ids)}",
            f"  - _Requirements: {', '.join(criterion_ids)}",
            f"  - Design: {designs}",
            f"  - Validation: {validation_command}",
            f"  - _Validation: {validation_command}",
            f"  - Done when: {done}",
        ])
        evidence = annotation.get("evidence", "")
        if isinstance(evidence, str) and evidence:
            lines.extend(["", evidence])
        lines.append("")
    (ROOT / "tasks.md").write_text("\n".join(lines), encoding="utf-8")


def validation_runner(identifier: str) -> str:
    if identifier == "VAL-CATALOG-001":
        return "python3 .agents/specs/comfy-parity/regenerate_all.py --check-twice"
    if identifier == "VAL-DOCS-001":
        return "python3 .agents/specs/comfy-parity/generate_documentation_catalogs.py"
    if identifier == "VAL-CLI-001":
        return "cargo test -p zed --features test-support comfy_cli_contract"
    if identifier == "VAL-FOUNDATION-001":
        return "cargo test -p comfy_test_support val_foundation_001"
    if identifier == "VAL-PROTOCOL-001":
        return "cargo test --locked -p comfy_types worker_protocol; cargo test --locked -p comfy_worker --test ipc_framing"
    if identifier in {"VAL-RUNTIME-PERSISTENCE-001", "VAL-RUNTIME-SETTINGS-001", "VAL-RUNTIME-TRUST-001"}:
        return f"cargo test -p comfy_runtime {identifier.casefold().replace('-', '_')}"
    if identifier == "VAL-OWNERSHIP-DOMAIN-001":
        return "cargo test -p comfy_test_support val_ownership_domain_001"
    if identifier == "VAL-OWNERSHIP-001":
        return "cargo test -p comfy_test_support val_ownership_001"
    if identifier == "VAL-LEGACY-ENGINE-001":
        return "cargo test --locked -p comfy_test_support --test no_python_engine val_legacy_engine_001"
    if identifier == "VAL-NODE-REGISTRY-001":
        return "cargo test -p comfy_nodes val_node_registry_001"
    if identifier == "VAL-MODEL-REGISTRY-001":
        return "cargo test -p comfy_model val_model_registry_001"
    if identifier == "VAL-GPUI-013":
        return "cargo test -p zed --features test-support val_gpui_013"
    if identifier.startswith("VAL-GPUI-") or identifier == "VAL-DESKTOP-001":
        return f"cargo test -p comfy_ui --features test-support {identifier.casefold().replace('-', '_')}"
    if identifier in {"VAL-HTTP-001", "VAL-WS-001", "VAL-NATIVE-API-001", "VAL-RECOVERY-004"}:
        return f"cargo test -p comfy_api {identifier.casefold().replace('-', '_')}"
    if identifier == "VAL-DEVICE-001":
        return "cargo test --locked -p comfy_tensor --all-features val_device_001"
    if identifier == "VAL-NUMERIC-FORMATS-001":
        return "cargo test --locked -p comfy_model --test numeric_formats val_numeric_formats_001"
    if identifier == "VAL-WEIGHT-ADAPTER-001":
        return "cargo test --locked -p comfy_model --test weight_adapter_runtime"
    if identifier == "VAL-PATCH-ADAPTER-001":
        return "cargo test --locked -p comfy_model --test patch_adapters"
    if identifier == "VAL-CONTROLNET-001":
        return "cargo test --locked -p comfy_model controlnet::tests"
    if identifier == "VAL-CONDITIONING-001":
        return "CARGO_INCREMENTAL=0 cargo test --locked -p comfy_test_support --test native_conditioning_integration val_conditioning_001"
    if identifier in {"VAL-CLIP-001", "VAL-PATCH-001", "VAL-VAE-001"}:
        return f"cargo test --locked -p comfy_model {identifier.casefold().replace('-', '_')}"
    if identifier == "VAL-MEMORY-001":
        return "; ".join([
            "cargo test --locked -p comfy_tensor val_memory_001",
            "cargo test --locked -p comfy_worker --test memory_conformance val_memory_001",
            "cargo test --locked -p comfy_worker --test ipc_framing packaged_worker_reports_preflight_oom_without_dispatch_or_restart",
        ])
    if identifier == "VAL-AUTOGRAD-001":
        return "; ".join([
            "cargo test -p comfy_tensor val_autograd_001",
            "cargo test --locked -p comfy_test_support --test autograd_breadth",
        ])
    if identifier in {"VAL-TENSOR-001", "VAL-RNG-001"}:
        return f"cargo test -p comfy_tensor {identifier.casefold().replace('-', '_')}"
    if identifier in {
        "VAL-MODEL-FORMAT-001",
        "VAL-MODEL-FAMILY-FOUNDATION-001",
        "VAL-MODEL-DETECTION-001",
        "VAL-MODEL-FAMILY-ROW-001",
        "VAL-MODEL-FAMILY-001",
        "VAL-LATENT-001",
    }:
        return f"cargo test -p comfy_model {identifier.casefold().replace('-', '_')}"
    if identifier in {
        "VAL-SAMPLING-FOUNDATION-001",
        "VAL-SAMPLER-001",
        "VAL-SCHEDULER-001",
    }:
        return f"cargo test -p comfy_sampler {identifier.casefold().replace('-', '_')}"
    if identifier.startswith("VAL-NODE-"):
        return f"cargo test -p comfy_nodes {identifier.casefold().replace('-', '_')}"
    if identifier == "VAL-PLUGIN-001":
        return "cargo test -p comfy_plugin_host val_plugin_001"
    if identifier == "VAL-PLUGIN-HOST-001":
        return "cargo test -p comfy_test_support val_plugin_host_001"
    if identifier == "VAL-WORKER-PLUGIN-001":
        return "CARGO_INCREMENTAL=0 cargo test -p comfy_test_support --test plugin_e2e val_worker_plugin_001 -- --nocapture"
    if identifier == "VAL-MEDIA-001":
        return "cargo test -p comfy_media val_media_001"
    if identifier == "VAL-METADATA-001":
        return "cargo test -p comfy_media val_metadata_001"
    if identifier == "VAL-RECOVERY-002":
        return "cargo test -p comfy_runtime val_recovery_002"
    if identifier.startswith("VAL-DOMAIN-"):
        return f"cargo test -p comfy_runtime {identifier.casefold().replace('-', '_')}"
    return f"cargo test -p comfy_test_support {identifier.casefold().replace('-', '_')}"


def write_validation() -> None:
    lines = [
        "# Validation: Native Rust/GPUI Comfy parity",
        "",
        "## Outcome and oracle boundary",
        "",
        "Validation compares identical deterministic fixtures against source behavior and native Zed, but source applications are development-only oracles. Recorded fixtures, normalization code, fingerprints, environments, and numeric tolerances are checked in; release tests do not require source trees, Python, JavaScript extension execution, external Comfy connectivity, accounts, paid services, credentials, or network access.",
        "",
        "A result is `observed` only when a recorded runtime probe actually ran. Existing tests may support `test-backed`; executable code may support `code-inferred`; documentation without corroboration remains `documented-only`; unavailable hardware/accounts/dependencies remain explicit uncertainty.",
        "",
        "## Deterministic fixture families",
        "",
        "- Lossless legacy/current workflow and prompt JSON, malformed graphs, list/lazy/blocker/expansion nodes, unknown fields, legacy plugin IDs, tabs, drafts, conflicts, and embedded PNG/WebP/FLAC metadata.",
        "- Tensor operation matrices over shape, dtype, layout, device, empty/scalar, NaN/infinity, views/copies, gradients, RNG seeds/counters/phases, cancellation, and unsupported capability.",
        "- Safe model-format corpus plus one shape-reduced detector/loader/forward fixture for each of 94 model families, patch/quantization variants, 33 latent formats, and all invalid/partial/mismatch/OOM cases.",
        "- Analytical tiny denoiser trajectories for all 44 samplers and exact scalar sigma arrays for all 9 schedulers, including boundary, NaN, cancellation, and callback ordering.",
        "- Every local/API node row with exact schema and independently applicable success, boundary, list/lazy, validation, cache/change, effect, failure, cancellation, persistence, and recovery cases.",
        "- HTTP, WebSocket, comfy-cli, Desktop IPC/preload/menu/window, settings, flags, formats, plugins, providers, codecs, localization, and source-file closure fixtures.",
        "",
        "## Environment and platform matrix",
        "",
        "| Dimension | Required coverage | Evidence rule |",
        "| --- | --- | --- |",
        "| Production boundary | Packaged release with no source trees, no Python on PATH, no Node extension host/browser, network disabled | Must pass native readiness and first slice; static inspection alone is insufficient |",
        "| Devices | Certified baseline: deterministic CPU and signed Apple Metal; optional CUDA, ROCm, DirectML, XPU, NPU, MLU, CoreX, and multi-device boundaries | Optional live-hardware rows stay external release gates; CoreX must remain compiled, zero-symbol, typed Unbound until its future specification is delivered |",
        "| Platforms | macOS, Windows, Linux package/data/permission/window/backend/codec behavior | Native branch plus platform test/lab; macOS observation cannot promote Windows/Linux |",
        "| Modes | GPUI local, headless native host, remote client of Zed host, offline, provider/cloud gated | GPUI and API share one native runtime; no external Comfy mode |",
        "| Accessibility | Keyboard-only, semantic tree, screen reader, focus, contrast, zoom, reduced motion | Production application must not default to inaccessible |",
        "| Failure injection | Invalid, empty, loading, partial, cancellation, timeout, OOM, device loss, plugin trap/hang, worker crash, app crash, conflict, permission denial, restart | Terminal state, durable record, resource convergence, and visible recovery are mandatory |",
        "",
        "## Numeric and media comparison policy",
        "",
        "Exact comparison is required for identifiers, schemas, shapes, strides, dtypes, layouts, integer/boolean values, CPU sigma arrays, versioned CPU RNG where supported, state transitions, errors, filenames, metadata, side effects, and ordering. Floating tolerances are recorded per operation/dtype/backend with absolute/relative/ULP rules and intermediate checkpoints. Final-image similarity cannot conceal operator, model, sampler, scheduler, or RNG substitution. Media comparison records decoded pixels/samples/frames/geometry plus color, orientation, timing, channels, metadata chunks, and container effects.",
        "",
        "## Numeric performance and convergence budgets",
        "",
        "Release-profile measurements record hardware, driver, OS, power mode, fixture digest, warmup, sample count, median, p95, and peak bytes. On the pinned CI reference CPU, the 512×512 five-node image slice completes in at most 2 seconds and the 32×32 four-step tiny diffusion slice in at most 5 seconds. A 1,000-node graph keeps pointer/key dispatch p95 at or below 8 ms and rendered-frame p95 at or below 16.7 ms during pan/zoom; a 10,000-node stress graph keeps interaction p95 below 50 ms. Worker CPU readiness is at most 2 seconds, a warm certified device worker at most 5 seconds, API/event projection p95 at most 50 ms, and the first preview arrives within 250 ms after a preview-capable checkpoint. Cancellation becomes visibly `cancelling` within 100 ms; CPU/WASM cooperative work terminates within 1 second, provider work within its 5-second adapter deadline, and non-preemptible device work either reaches a fence or the worker is terminated within 10 seconds. Ten seconds after terminal cancellation/crash, live task/file/handle counts return to baseline and accounted memory is within the larger of 1 percent or 64 MiB of baseline. A budget miss is a release failure unless the affected conditional platform row remains explicitly uncertified.",
        "",
        "## Certification scope and external release gates",
        "",
        "Implementation completion requires deterministic CPU conformance, strict verification of any supplied CPU attestation, the retained signed Apple Metal baseline evidence, and fail-closed unavailable-path validation for every compiled optional adapter. Creating or refreshing the signed CPU attestation requires the approved external PKCS#8 key and is not an implementation task. Live certification for ROCm, DirectML, XPU, NPU, MLU, CUDA, and multi-device modes remains an external release gate that may be claimed only on the exact hardware and driver environment. CoreX ABI, semantic, production-integration, signing, and hardware work is transferred to `.agents/specs/comfy-corex-enablement/`; this pack validates only its compiled zero-symbol structural adapter and canonical typed `Unbound` state. An absent gate is never represented as a pass and does not weaken production fail-closed behavior.",
        "",
        "## Scenarios",
        "",
    ]
    for identifier, (title, layer, fixture, procedure) in VALIDATIONS.items():
        pass_artifact = f"exit status 0 plus `target/comfy-parity/{identifier.casefold()}.json` containing fixture digests, environment/backend identity, per-case results, and no unexplained skipped row."
        if identifier in {"VAL-CLIP-001", "VAL-PATCH-001", "VAL-VAE-001", "VAL-CONTROLNET-001", "VAL-CONDITIONING-001"}:
            pass_artifact = (
                f"exit status 0 plus `target/comfy-parity/{identifier.casefold()}.json` "
                "using schema version 1 with validation and environment identity, truthful "
                "partial or passed overall status, aggregate summary, current sole-producer "
                "path and SHA-256, current per-task implementation paths and SHA-256 values, "
                "and unique exact contract records binding contract ID, owning task ID, pinned "
                "source and symbol SHA-256 values, passed status, and non-empty unique case IDs. "
                "Every claimed task result has zero failures and skips; partial artifacts claim "
                "only their exact passed rows."
            )
        if identifier == "VAL-CATALOG-001":
            pass_artifact = (
                "exit status 0 from the exact runner after the source-snapshot manifest "
                "matches and both complete regeneration passes produce no changed paths. "
                "The checked-in generated outputs and command result are the evidence; this "
                "command-only gate emits no separate target JSON artifact."
            )
        if identifier == "VAL-DEVICE-001":
            pass_artifact += " The Apple Metal baseline retains its signed artifact under `catalogs/native-device-certification/`; a supplied CPU artifact must verify cryptographically but may remain explicitly stale as an external release gate; optional accelerator artifacts are accepted only as external target-lab evidence."
        if identifier == "VAL-MODEL-FAMILY-ROW-001":
            pass_artifact = "exit status 0 plus one deterministic artifact per executed fixture under `target/comfy-parity/val-model-family-row-001/`, each containing exact source/fixture/provenance digests, environment/backend identity, per-case results, and zero failures or skips."
        if identifier == "VAL-NODE-002":
            pass_artifact += (
                " While the node task graph is incomplete, a focused foundation producer may "
                "identify an explicit non-release scope in this artifact; final release closure "
                "must replace it with the aggregate every-row artifact, and representative-only "
                "evidence still fails."
            )
        lines.extend([
            f"### {identifier}: {title}",
            "",
            f"- Type: {layer}.",
            f"- Fixture: {fixture}.",
            f"- Command/runner: `{validation_runner(identifier)}`.",
            f"- Procedure and expected signal: {procedure}",
            f"- Pass artifact: {pass_artifact}",
            "",
        ])
    lines.extend([
        "## Validation execution and gates",
        "",
        "Implementation tasks run targeted crate/domain/GPUI tests and `./script/clippy`. Closure runs every generator twice, every applicable unit/protocol/GPUI/visual/E2E/persistence/failure/accessibility/platform/security/performance scenario available for the CPU/Apple Metal baseline, fail-closed compile and unavailable-path checks for optional backends, the package boundary scan, registry/source-file reconciliation, forward and reverse traceability, independent completeness and implementation-readiness audits, and:",
        "",
        "```sh",
        "python3 .agents/skills/coding/scripts/validate_spec.py .agents/specs/comfy-parity --require-complete",
        "```",
        "",
        "A missing runtime, account, provider, codec, dependency, signing key, or optional device does not become a pass. It remains a named external release gate or uncertainty with the affected feature IDs, planned lab, safe default, and consequence. Such external gates do not block implementation completion, but no optional backend status changes to `equivalent` or `certified` until the exact row's target evidence exists. CoreX remains typed Unbound regardless of local files until the separate future specification completes every proprietary admission gate.",
        "",
    ])
    (ROOT / "validation.md").write_text("\n".join(lines), encoding="utf-8")


def write_mapping(
    tasks: list[dict[str, object]],
    special_mapping: dict[str, list[str]],
    criteria: dict[int, list[str]],
) -> None:
    special = special_feature_tasks(tasks, special_mapping)
    special_task_ids = {identifier for values in special.values() for identifier in values}
    task_criteria: dict[str, list[str]] = {}
    criterion_candidates: dict[str, list[str]] = defaultdict(list)
    feature_scoped_task_ids: list[str] = []
    for item in tasks:
        identifier = str(item["id"])
        explicit_criterion_ids = [str(value) for value in item["criterion_ids"]]
        mapped_criteria = explicit_criterion_ids or [
            criterion
            for requirement in sorted(set(int(value) for value in item["requirements"]))
            for criterion in criteria[requirement]
        ]
        task_criteria[identifier] = mapped_criteria
        for criterion in mapped_criteria:
            criterion_candidates[criterion].append(identifier)
        if bool(item["feature_scoped"]):
            feature_scoped_task_ids.append(identifier)
    requirement_candidates: dict[int, list[str]] = defaultdict(list)
    for item in tasks:
        identifier = str(item["id"])
        if identifier in special_task_ids:
            continue
        explicit_criterion_ids = [str(value) for value in item["criterion_ids"]]
        mapped_requirements = (
            sorted({int(value.split(".", 1)[0]) for value in explicit_criterion_ids})
            if explicit_criterion_ids
            else [int(value) for value in item["requirements"]]
        )
        for requirement in mapped_requirements:
            requirement_candidates[requirement].append(identifier)
    requirement_tasks = {
        requirement: list(dict.fromkeys(requirement_candidates[requirement]))
        for requirement in sorted(requirement_candidates)
    }
    referenced_task_ids = {
        identifier
        for values in requirement_tasks.values()
        for identifier in values
    } | special_task_ids
    identifier_fields = ("feature_id", "record_id", "operation_id", "autograd_id", "rng_id")
    for item in tasks:
        identifier = str(item["id"])
        if identifier in referenced_task_ids:
            continue
        anchor_candidates: list[str] = []
        for read_path in item["reads"]:
            catalog_path = CATALOGS / Path(str(read_path)).name
            if not catalog_path.exists() or catalog_path.suffix != ".csv":
                continue
            with catalog_path.open(newline="", encoding="utf-8") as handle:
                for row in csv.DictReader(handle):
                    feature_id = next((row.get(field, "") for field in identifier_fields if row.get(field)), "")
                    if feature_id:
                        anchor_candidates.append(feature_id)
        if anchor_candidates:
            unique_candidates = sorted(set(anchor_candidates))
            offset = int(hashlib.sha256(identifier.encode("utf-8")).hexdigest()[:8], 16) % len(unique_candidates)
            anchor = unique_candidates[offset]
        else:
            anchor = "COMFY-COMPAT-058"
        special.setdefault(anchor, []).append(identifier)
        referenced_task_ids.add(identifier)
    special = {feature_id: sorted(set(values)) for feature_id, values in sorted(special.items())}
    feature_criterion_overrides: dict[str, list[str]] = {}
    for catalog_name, mapped_criteria in (
        ("backend-http-routes.csv", TASK_20_HTTP_CRITERIA),
        ("backend-websocket-events.csv", TASK_20_WEBSOCKET_CRITERIA),
        ("frontend-commands.csv", ["15.1", "20.1"]),
        ("frontend-keybindings.csv", ["15.1", "20.1"]),
        ("frontend-menus.csv", ["20.1"]),
        ("frontend-component-surfaces.csv", ["20.1"]),
    ):
        with (CATALOGS / catalog_name).open(newline="", encoding="utf-8") as handle:
            for row in csv.DictReader(handle):
                feature_id = row.get("feature_id", "")
                if feature_id:
                    feature_criterion_overrides[feature_id] = mapped_criteria
    feature_validation_overrides: dict[str, list[str]] = {}
    shell_feature_ids: set[str] = set()
    for catalog_name in (
        "frontend-commands.csv",
        "frontend-keybindings.csv",
        "frontend-menus.csv",
        "frontend-component-surfaces.csv",
    ):
        with (CATALOGS / catalog_name).open(newline="", encoding="utf-8") as handle:
            catalog_feature_ids = {
                row["feature_id"] for row in csv.DictReader(handle) if row.get("feature_id")
            }
        duplicate_feature_ids = shell_feature_ids & catalog_feature_ids
        if duplicate_feature_ids:
            raise RuntimeError(
                f"duplicate shell feature ownership in {catalog_name}: "
                f"{sorted(duplicate_feature_ids)[:20]}"
            )
        shell_feature_ids.update(catalog_feature_ids)
        for feature_id in catalog_feature_ids:
            feature_validation_overrides[feature_id] = ["VAL-GPUI-012"]
    if len(shell_feature_ids) != 1_193:
        raise RuntimeError(
            "shell validation override must cover exactly 1,193 features, "
            f"found {len(shell_feature_ids)}"
        )

    graph_context_criteria = [
        "15.1",
        "15.2",
        "15.4",
        "15.5",
        "20.1",
        "20.2",
        "20.3",
        "20.6",
    ]
    graph_context_feature_ids: set[str] = set()
    with (CATALOGS / "native-menu-dispositions.csv").open(
        newline="", encoding="utf-8"
    ) as handle:
        for row in csv.DictReader(handle):
            if row.get("owner_task_id") == "comfy-parity-graph-context-menu-surfaces":
                feature_criterion_overrides[row["feature_id"]] = graph_context_criteria
                graph_context_feature_ids.add(row["feature_id"])
                feature_validation_overrides.setdefault(row["feature_id"], []).append(
                    "VAL-GPUI-014"
                )
    if len(graph_context_feature_ids) != 63:
        raise RuntimeError(
            "graph context menu validation override must cover exactly 63 features"
        )
    comfy_build_boundary_feature_id = "COMFY-DESKTOP-206"
    feature_criterion_overrides[comfy_build_boundary_feature_id] = list(criteria[45])
    feature_validation_overrides[comfy_build_boundary_feature_id] = [
        "VAL-COMFY-BUILD-001"
    ]
    special.setdefault(comfy_build_boundary_feature_id, []).append(
        "comfy-parity-opt-in-product-build-boundary"
    )
    special[comfy_build_boundary_feature_id] = sorted(
        set(special[comfy_build_boundary_feature_id])
    )
    criterion_designs = {
        criterion: CRITERION_DESIGN_OVERRIDES.get(criterion, REQ_DESIGNS[int(criterion.split(".", 1)[0])])
        for values in criteria.values()
        for criterion in values
    }
    criterion_validations = {
        criterion: CRITERION_VALIDATION_OVERRIDES.get(
            criterion, REQ_VALIDATIONS[int(criterion.split(".", 1)[0])]
        )
        for values in criteria.values()
        for criterion in values
    }
    missing_requirements = set(criteria) - set(requirement_tasks)
    if missing_requirements:
        raise RuntimeError(f"requirements without generic task mapping: {sorted(missing_requirements)}")
    payload = {
        "requirement_criteria_counts": {str(number): len(values) for number, values in criteria.items()},
        "requirement_tasks": {str(number): values for number, values in sorted(requirement_tasks.items())},
        "requirement_designs": {str(number): values for number, values in sorted(REQ_DESIGNS.items())},
        "requirement_validations": {str(number): values for number, values in sorted(REQ_VALIDATIONS.items())},
        "criterion_tasks": {
            criterion: list(dict.fromkeys(values))
            for criterion, values in sorted(criterion_candidates.items())
        },
        "criterion_designs": criterion_designs,
        "criterion_validations": criterion_validations,
        "task_criteria": task_criteria,
        "feature_criterion_overrides": feature_criterion_overrides,
        "feature_validation_overrides": feature_validation_overrides,
        "feature_scoped_task_ids": sorted(feature_scoped_task_ids),
        "special_feature_tasks": special,
        "specialized_feature_tasks": special_mapping,
        "task_ids": [item["id"] for item in tasks],
        "validation_ids": list(VALIDATIONS),
        "design_ids": [f"D{number}" for number, _, _ in DECISIONS],
        "certified_baseline_backends": ["cpu", "metal"],
        "external_release_certification_gates": {
            "cpu_signed_hardware_attestation": {
                "completion_blocking": False,
                "required_implementation_behavior": [
                    "deterministic CPU conformance",
                    "strict verification of any supplied certificate against the independent trust anchor",
                ],
                "external_inputs": ["approved PKCS#8 signing key", "release lab custody"],
            },
            "optional_accelerator_hardware": {
                "completion_blocking": False,
                "legacy_task_ids": sorted(EXTERNAL_HARDWARE_CERTIFICATION_TASK_IDS),
                "rule": "unavailable hardware remains unclaimed and cannot be reported as passed or certified",
            },
        },
        "scope_transfers": {
            "corex_enablement": {
                "destination_spec": ".agents/specs/comfy-corex-enablement",
                "moved_task_ids": sorted(MOVED_COREX_ENABLEMENT_TASK_IDS),
                "retained_task_id": "comfy-parity-corex-provenance-blocked-structural-foundation",
                "retained_state": "compiled zero-symbol adapter; canonical typed Unbound; no runtime loader or certificate projection",
            }
        },
    }
    (CATALOGS / "native-spec-mapping.json").write_text(
        json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )


def write_native_fixture_contracts() -> None:
    (CATALOGS / "native-diffusion-fixture.json").write_text(
        json.dumps(DIFFUSION_FIXTURE, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )


def write_directml_abi_execution_state() -> None:
    missing_evidence = []
    for relative_path, required_source in DIRECTML_EXECUTION_SOURCE_EVIDENCE.items():
        source_path = REPOSITORY_ROOT / relative_path
        if not source_path.is_file() or required_source not in source_path.read_text(
            encoding="utf-8"
        ):
            missing_evidence.append(f"{relative_path}#{required_source}")
    if missing_evidence:
        raise RuntimeError(
            "DirectML cannot be cataloged as execution-supported without its production "
            f"implementation surfaces: {missing_evidence}"
        )

    catalog_path = CATALOGS / "native-backend-abi" / "directml.json"
    payload = json.loads(catalog_path.read_text(encoding="utf-8"))
    if payload.get("backend") != "directml":
        raise RuntimeError("DirectML ABI catalog has the wrong backend identity")
    if payload.get("execution_task_id") != (
        "comfy-parity-directml-execution-resource-ownership-consolidation"
    ):
        raise RuntimeError("DirectML ABI catalog has the wrong execution owner task")
    payload["status"] = DIRECTML_ABI_EXECUTION_STATUS
    payload["unsafe_ffi_owner"] = DIRECTML_UNSAFE_FFI_OWNER
    catalog_path.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")


def main() -> None:
    criteria = requirement_criteria()
    tasks, special_mapping = all_tasks()
    write_native_fixture_contracts()
    write_directml_abi_execution_state()
    write_design(criteria)
    write_tasks(tasks, criteria)
    write_validation()
    write_mapping(tasks, special_mapping, criteria)
    print(
        f"Generated native planning documents: {sum(len(values) for values in criteria.values())} criteria, "
        f"{len(DECISIONS)} decisions, {len(tasks)} tasks, {len(VALIDATIONS)} validations."
    )


if __name__ == "__main__":
    main()
